def lm(f,p0,iters=200):
    p=np.array(p0,float); lam=1e-2
    r=lambda p: f(p)-y
    for _ in range(iters):
        rr=r(p); J=np.zeros((len(y),len(p)))
        for j in range(len(p)):
            dp=np.zeros(len(p)); dp[j]=1e-7*max(1,abs(p[j])); J[:,j]=(r(p+dp)-rr)/dp[j]
        H=J.T@J; g=J.T@rr
        try: step=np.linalg.solve(H+lam*np.diag(np.diag(H)+1e-9),-g)
        except: break
        pn=p+step
        if np.all(np.isfinite(r(pn))) and np.sum(r(pn)**2)<np.sum(rr**2): p=pn; lam*=0.3
